// <work-user> — avatar + identity menu, bound to the current session.
//
// Reads the identity seam (over this.host): shows the signed-in user's avatar
// (image or initials), and on click reveals a menu with name/email + sign-out.
// Subscribes to the seam, so it updates live when the session changes elsewhere
// (e.g. <work-auth> resolves a sign-in). Sign-out drives the seam and emits
// `work-auth-changed` {user:null}. When anonymous it renders nothing (a <work-gate>
// or <work-auth> handles the anon case).
//
// Variants:  variant = "menu" | "compact"  (compact = avatar only, no name)
// Events:  work-auth-changed { user, providers }  (on sign-out)
// Usage:  <work-user></work-user>   ·   <work-user variant="compact"></work-user>
import { WbElement, html, css, define } from "../../core/element.js";
import { defineVariants, variantAttrs } from "../../core/variants.js";
import { getIdentity } from "./identity.js";

const VARIANTS = defineVariants({
  variant: { options: ["menu", "compact"], default: "menu" },
});

export class WorkUser extends WbElement {
  static variants = VARIANTS;
  static props = [...variantAttrs(VARIANTS), "open"];

  static styles = css`
    :host { display: inline-block; font-family: var(--work-font); color: var(--work-fg); position: relative; }
    :host([hidden]) { display: none; }
    .trigger {
      display: inline-flex; align-items: center; gap: var(--work-space-2);
      padding: var(--work-space-1) var(--work-space-2) var(--work-space-1) var(--work-space-1);
      border: 1.5px solid var(--work-border); border-radius: var(--work-radius-pill);
      background: var(--work-surface); color: var(--work-fg); cursor: pointer;
      transition: background var(--work-dur) var(--work-ease), border-color var(--work-dur) var(--work-ease),
                  box-shadow var(--work-dur) var(--work-ease);
    }
    .trigger:hover { background: var(--work-surface-soft); border-color: var(--work-border-strong); }
    .trigger:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--work-ring); }
    :host([variant="compact"]) .trigger { padding: 0; border-radius: 50%; border-color: transparent; }
    :host([variant="compact"]) .name { display: none; }

    .avatar {
      width: 28px; height: 28px; flex: none; border-radius: 50%;
      display: inline-grid; place-items: center; overflow: hidden;
      background: var(--work-brand); color: var(--work-on-brand);
      font: 700 11px var(--work-font-mono); letter-spacing: .02em;
    }
    .avatar img { width: 100%; height: 100%; object-fit: cover; }
    .name { font-size: var(--work-text-sm); font-weight: 600; max-width: 14ch;
      overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .caret { width: 12px; height: 12px; color: var(--work-fg-subtle); flex: none; }
    :host([variant="compact"]) .caret { display: none; }

    .menu {
      position: absolute; top: calc(100% + 6px); right: 0; min-width: 220px; z-index: 30;
      border: 1px solid var(--work-border); border-radius: var(--work-radius);
      background: var(--work-surface); box-shadow: var(--work-shadow); padding: var(--work-space-2);
      display: none;
    }
    :host([open]) .menu { display: block; }
    .who { display: flex; align-items: center; gap: var(--work-space-3);
      padding: var(--work-space-2) var(--work-space-2) var(--work-space-3); }
    .who .avatar { width: 36px; height: 36px; font-size: var(--work-text-md); }
    .who .meta { min-width: 0; }
    .who .meta .n { font-weight: 600; font-size: var(--work-text); }
    .who .meta .e { color: var(--work-fg-muted); font-size: var(--work-text-sm);
      overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .sep { height: 1px; background: var(--work-border); margin: var(--work-space-1) 0; }
    .item {
      display: flex; align-items: center; gap: var(--work-space-2); width: 100%;
      padding: var(--work-space-2) var(--work-space-2); border: 0; border-radius: var(--work-radius-sm);
      background: none; color: var(--work-fg); font: var(--work-text) var(--work-font); text-align: left;
      cursor: pointer;
    }
    .item:hover { background: var(--work-surface-soft); }
    .item.danger { color: var(--work-err); }
    .item svg { width: 15px; height: 15px; flex: none; }
  `;

  get identity() {
    return this._identity || (this._identity = getIdentity());
  }
  set identity(cap) {
    this._unsub?.();
    this._identity = cap;
    this._listen();
    if (this._connected) this.requestUpdate();
  }

  _listen() {
    this._unsub = this.identity.subscribe(() => this.requestUpdate());
  }

  _initials(name, email) {
    const src = name || email || "?";
    const parts = src.replace(/@.*/, "").split(/[\s._-]+/).filter(Boolean);
    return ((parts[0]?.[0] || "") + (parts[1]?.[0] || "")).toUpperCase() || src[0].toUpperCase();
  }

  async connectedCallback() {
    super.connectedCallback();
    if (!this._wired) {
      this._wired = true;
      this._listen();
      // close on outside click
      this._onDoc = (e) => { if (!this.contains(e.target)) this.removeAttribute("open"); };
      document.addEventListener("click", this._onDoc);
    }
    // resolve a possibly-async real session
    await this.identity.session();
    this.requestUpdate();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._unsub?.();
    document.removeEventListener("click", this._onDoc);
  }

  async _signOut() {
    this.removeAttribute("open");
    const snap = await this.identity.signOut();
    this.dispatchEvent(new CustomEvent("work-auth-changed", { bubbles: true, composed: true, detail: snap }));
  }

  _avatar(user) {
    return user.avatar
      ? html`<span class="avatar"><img src=${user.avatar} alt="" /></span>`
      : html`<span class="avatar">${this._initials(user.name, user.email)}</span>`;
  }

  render() {
    const { user } = this.identity.peek();
    if (!user) { this.setAttribute("hidden", ""); return ""; }
    this.removeAttribute("hidden");
    return html`
      <button class="trigger" part="trigger" aria-haspopup="menu" aria-label="Account"
        @click=${() => this.toggleAttribute("open")}>
        ${this._avatar(user)}
        <span class="name">${user.name || user.email || "Account"}</span>
        <svg class="caret" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>
      </button>
      <div class="menu" part="menu" role="menu">
        <div class="who">
          ${this._avatar(user)}
          <div class="meta">
            <div class="n">${user.name || "—"}</div>
            <div class="e">${user.email || ""}</div>
          </div>
        </div>
        <div class="sep"></div>
        <button class="item signout danger" role="menuitem" part="signout" @click=${() => this._signOut()}>
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5"/><path d="M21 12H9"/></svg>
          Sign out
        </button>
      </div>`;
  }
}

define("work-user", WorkUser);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP), or `kernel` (oql.wasm) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// Variants — the cva-style contract for web components.
//
// Variants are REFLECTED ATTRIBUTES the component CSS targets via :host([...]).
// This util doesn't generate classes; it (1) declares the allowed values +
// defaults for an element (so authoring is typed/validated and the design-lint
// can check conformance), and (2) normalizes the live attribute, applying the
// default when unset or invalid. The actual styling lives in the component CSS:
//
//   static styles = `
//     :host([variant="solid"]) button { background: var(--work-brand); }
//     :host([size="sm"])      button { padding: var(--work-space-1) var(--work-space-2); }
//   `;
//
// Usage in an element:
//   static variants = defineVariants({
//     variant: { options: ["solid", "soft", "ghost"], default: "solid" },
//     size:    { options: ["sm", "md", "lg"],        default: "md" },
//     tone:    { options: ["brand", "neutral", "ok", "warn", "err"], default: "brand" },
//   });
//   // in render(): this.variant("variant") -> the resolved value

export function defineVariants(spec) {
  return spec;
}

/** Resolve a variant attribute on `el` to a valid value (default on miss). */
export function resolveVariant(el, spec, name) {
  const def = spec[name];
  if (!def) return el.getAttribute(name);
  const v = el.getAttribute(name);
  return def.options.includes(v) ? v : def.default;
}

/** Every variant attribute name an element declares (for observedAttributes). */
export function variantAttrs(spec) {
  return Object.keys(spec || {});
}

/** Design-lint helper: report any variant attr set to a non-allowed value. */
export function lintVariants(el, spec) {
  const bad = [];
  for (const [name, def] of Object.entries(spec || {})) {
    const v = el.getAttribute(name);
    if (v != null && !def.options.includes(v)) bad.push({ name, value: v, allowed: def.options });
  }
  return bad;
}

// workponents · auth domain — the identity seam.
//
// The reinvention: identity is a HOST capability, not a per-provider widget.
// The elements never know whether the session is backed by Clerk, Auth0, WorkOS,
// or BetterAuth — those are server-side wirings behind the Dock. The elements
// read ONE small `auth` capability layered on `this.host`:
//
//   • session()           → current { user, providers } | { user: null, providers }
//   • signIn({method, provider, email, password})  → resolves a session
//   • signOut()           → clears the session
//   • subscribe(fn)        → notified on every session change (fn(session))
//
// This file implements that seam OVER the existing Host (`src/core/host.js`),
// WITHOUT editing core. When a runtime URL is configured it routes to the
// runtime's `/auth/*` endpoints (provider-agnostic — the runtime resolves the
// real provider); standalone (no runtime), a MOCK identity lets the elements
// render + demo a full sign-in → authed → sign-out cycle with no backend.
//
// SUGGESTED CORE ADDITION (noted, not made): a first-class `host.auth` accessor
// returning an `AuthCapability` so every domain shares ONE identity instance and
// the seam isn't re-created per element family. Until then we cache a singleton
// here, keyed off the active Host.
//
// Host endpoint contract (provider-agnostic, the runtime wires the provider):
//   GET  /auth/session                 → { user, providers }
//   POST /auth/signin  {method, provider, email?, password?}  → { user, providers }
//   POST /auth/signout                 → { user: null, providers }
// where  user = { id, name, email, avatar?, roles?: string[] } | null
//        providers = [{ id, name }]   (the sign-in options the surface renders)

import { getHost } from "../../core/host.js";

/** The default provider list a mock/preview identity offers. */
export const DEFAULT_PROVIDERS = [
  { id: "google", name: "Google" },
  { id: "github", name: "GitHub" },
  { id: "workos", name: "SSO" },
];

/** A live identity capability bound to a Host (real) or a mock (standalone). */
export class AuthCapability extends EventTarget {
  /** @param {{ host?: any, mock?: boolean, providers?: any[], seed?: any }} [opts] */
  constructor(opts = {}) {
    super();
    this._host = opts.host || null;
    // Mock when explicitly asked OR when no runtime backs the Host.
    this._mock = opts.mock != null ? opts.mock : !(this._host && this._host.available?.("auth"));
    this._providers = opts.providers || DEFAULT_PROVIDERS;
    this._user = opts.seed?.user || null;
    this._loaded = false;
  }

  get isMock() {
    return this._mock;
  }

  /** Current session snapshot. Loads once from the Host when real. */
  async session() {
    if (this._mock) return this._snapshot();
    if (!this._loaded) {
      try {
        const s = await this._host.request("/auth/session", { method: "GET" });
        this._user = s?.user ?? null;
        if (Array.isArray(s?.providers)) this._providers = s.providers;
      } catch {
        // Runtime unreachable → fall back to a preview identity, don't throw.
        this._mock = true;
      }
      this._loaded = true;
    }
    return this._snapshot();
  }

  /** The synchronous best-known session (no fetch); elements seed UI with this. */
  peek() {
    return this._snapshot();
  }

  /**
   * Resolve a sign-in. method = "oauth" (with provider) | "password" | "magic".
   * Real: POSTs /auth/signin. Mock: fabricates a plausible session.
   */
  async signIn({ method = "password", provider = null, email = null, password = null } = {}) {
    if (this._mock) {
      const name = method === "oauth"
        ? this._providerName(provider)
        : (email ? email.split("@")[0] : "You");
      this._user = {
        id: "mock-" + (provider || method),
        name: this._titleize(name),
        email: email || (provider ? `you@${provider}.example` : "you@example.com"),
        avatar: null,
        roles: ["member"],
        via: provider || method,
      };
      return this._change();
    }
    const s = await this._host.request("/auth/signin", {
      body: { method, provider, email, password },
    });
    this._user = s?.user ?? null;
    if (Array.isArray(s?.providers)) this._providers = s.providers;
    return this._change();
  }

  /** Magic-link request — mock resolves immediately; real returns a pending hint. */
  async requestMagicLink({ email } = {}) {
    if (this._mock) return this.signIn({ method: "magic", email });
    return this._host.request("/auth/signin", { body: { method: "magic", email } });
  }

  async signOut() {
    if (!this._mock) {
      try { await this._host.request("/auth/signout", {}); } catch { /* clear locally regardless */ }
    }
    this._user = null;
    return this._change();
  }

  /** Subscribe to session changes; returns an unsubscribe fn. */
  subscribe(fn) {
    const h = (e) => fn(e.detail);
    this.addEventListener("change", h);
    return () => this.removeEventListener("change", h);
  }

  get providers() {
    return this._providers;
  }

  _snapshot() {
    return { user: this._user ? { ...this._user } : null, providers: this._providers };
  }

  _change() {
    const snap = this._snapshot();
    this.dispatchEvent(new CustomEvent("change", { detail: snap }));
    return snap;
  }

  _providerName(id) {
    return this._providers.find((p) => p.id === id)?.name || id || "Account";
  }

  _titleize(s) {
    return String(s).replace(/(^|[\s._-])(\w)/g, (_, sep, c) => (sep ? " " : "") + c.toUpperCase());
  }
}

// One identity per active Host (until core grows a `host.auth`). A page/workbook
// can override with configureIdentity() to force a mock or seed a session.
let _identity = null;

/** Configure the shared identity (call once; e.g. a demo seeds a mock). */
export function configureIdentity(opts = {}) {
  _identity = new AuthCapability({ host: opts.host || getHost(), ...opts });
  return _identity;
}

/** The shared identity capability (auto-created over the active Host). */
export function getIdentity() {
  if (!_identity) _identity = new AuthCapability({ host: getHost() });
  return _identity;
}
